mapper.select:
SELECT seat_seq AS seatSeq, schedule_seq AS scheduleSeq, car_no AS carNo, seat_no AS seatNo, seat_grade AS seatGrade, status, version FROM seat WHERE schedule_seq = #{scheduleSeq}
AND car_no = #{carNo}
ORDER BY car_no ASC, CAST(NULLIF(regexp_replace(seat_no, '\D', '', 'g'), '') AS INTEGER) ASC, regexp_replace(seat_no, '\d', '', 'g') ASC

mapper.update:
UPDATE seat
SET status = #{newStatus},
    version = version + 1
WHERE schedule_seq = #{scheduleSeq}
  AND car_no = #{carNo}
  AND seat_no = #{seatNo}
  AND status = #{currentStatus}
